import { parsePagedWithItemSchema, parseWithSchema } from "./parse-with-schema.js";

/**
 * Generic per-item paginated parser — kept for callers that need
 * an `(raw) => Result<PaginatedResponse<T>>` thunk (the legacy
 * `parsePageOf(parseItem)` shape). The item parser is decoupled from
 * the envelope so callers compose freely.
 */
export function parsePageOf<T>(parseItem: (raw: unknown) => Result<T, ApiError>): (
  raw: unknown
) => Result<
  {
    readonly items: readonly T[];
    readonly total: number;
    readonly page: number;
    readonly limit: number;
  },
  ApiError
> {
  return (raw) => {
    if (raw === null || typeof raw !== "object") {
      return err({ kind: "upstream", detail: "malformed page envelope" });
    }
    const r = raw as { items?: unknown; total?: unknown; page?: unknown; limit?: unknown };
    if (
      !Array.isArray(r.items) ||
      typeof r.total !== "number" ||
      typeof r.page !== "number" ||
      typeof r.limit !== "number"
    ) {
      return err({ kind: "upstream", detail: "page envelope: wrong field types" });
    }
    const out: T[] = [];
    for (const item of r.items) {
      const parsed = parseItem(item);
      if (parsed.isErr()) return err(parsed.error);
      out.push(parsed.value);
    }
    return ok({ items: out, total: r.total, page: r.page, limit: r.limit });
  };
}

/** Generic per-item array parser. */
export function parseArrayOf<T>(
  parseItem: (raw: unknown) => Result<T, ApiError>
): (raw: unknown) => Result<readonly T[], ApiError> {
  return (raw) => {
    if (!Array.isArray(raw)) return err({ kind: "upstream", detail: "expected array" });
    const out: T[] = [];
    for (const item of raw) {
      const r = parseItem(item);
      if (r.isErr()) return err(r.error);
      out.push(r.value);
    }
    return ok(out);
  };
}

