const OrgSchema = schemas.OrgResponse.pick({
  id: true,
  name: true,
  owner_id: true,
  is_active: true,
  created_at: true,
}).strip();

export const parseOrg = (raw: unknown): Result<OrgResponse, ApiError> =>
  parseWithSchema(OrgSchema, raw, "org") as Result<OrgResponse, ApiError>;

